/* src/styles/6-components/inverse-surface.css */
/**
 * Inverse Surface — 짙은 면 위에 올라가는 부품의 색을 한꺼번에 바꾼다
 *
 * 카탈로그 부품(tab·btn·링크·초점 링)은 의미 토큰을 읽는다. 이 블록은 부품을 덮어쓰지 않고
 * 블록 안에서 의미 토큰이 가리키는 값을 밝은 단계로 바꾼다. 면의 색은 --surface로 받는다.
 *   <section class="section section--intro inverse-surface">…</section>
 *   <div class="inverse-surface" style="--surface: var(--color-gray-90)">…</div>
 * 근거: design-intelligence.md §5-2 「짙은 면이 시작되면 그 안의 부품도 바꾼다」
 * 레이어 밖에 둔다 — 블록 카탈로그(cover·link-rows)의 면 색과 같은 층에서 겨룬다.
 */
.inverse-surface {
  --color-text: var(--color-gray-0);
  --color-text-bolder: var(--color-gray-0);
  --color-text-subtle: var(--color-primary-10);
  --color-text-primary: var(--color-primary-20);
  --color-text-inverse: var(--color-primary-90);
  --color-primary: var(--color-primary-20);
  --color-link: var(--color-gray-0);
  --color-link-hover: var(--color-primary-20);
  --color-link-pressed: var(--color-primary-10);
  --color-link-visited: var(--color-gray-0);
  --color-point: var(--color-point-30);
  --color-border: var(--color-primary-60);
  --color-border-light: var(--color-primary-70);
  --color-border-primary: var(--color-primary-20);
  --color-button-primary-fill: var(--color-gray-0);
  --color-button-primary-fill-hover: var(--color-primary-10);
  --color-button-primary-fill-pressed: var(--color-primary-20);

  @apply bg-[var(--surface,var(--color-primary-80))] text-[var(--color-text)];
}

/* src/styles/6-components/display-title.css */
/**
 * Display Title — 면 제목 (블록 카탈로그 news-deck·field-shore·link-lines가 함께 쓴다)
 *   <h2 class="display-title">새 소식</h2>
 *   제목 서체(--font-heading)로 크게 세운다. 색은 놓인 면의 글자색을 따른다.
 *   블록 예외(contracts/block-exceptions.json): 행간 1.2.
 *   KRDS 기준 밖(운영자 승인 대기): 크기 3.2~5.6rem(heading-xlarge 4rem 상한)·행간 1.2(150% 기준)
 * 레이어 밖에 둔다 — 블록이 여백을 덮어쓴다.
 */
.display-title {
  @apply m-0 mb-[4rem] [font-family:var(--font-heading)] font-semibold tracking-normal [word-break:keep-all] [text-wrap:balance];

  font-size: clamp(3.2rem, 4vw, 5.6rem);
  line-height: 1.2;
}

/* src/styles/6-components/news-deck.css */
/**
 * News Deck — 짙은 면 소식 (블록 카탈로그 news-deck · design-intelligence §6-3 N1 + N2)
 *   <section class="section section--notice inverse-surface news-deck" aria-labelledby="news-deck-title">
 *     <div class="container news-deck__grid">
 *       <div class="news-deck__board"><h2 class="display-title">새 소식</h2> <div class="tab">…post-list…more-link…</div></div>
 *       <aside class="due-track">…</aside>
 *     </div>
 *   </section>
 *   inverse-surface가 바꾼 토큰 위에서 면 색과 선·보조 글자색만 다시 잡는다.
 *   목록의 첫 글 한 건만 제목 서체 큰 글자로 세우고 나머지는 보통 굵기로 낮춘다. 마감 칸은 목록 높이에 맞춰 늘어난다.
 *   블록 예외(contracts/block-exceptions.json): 섹션 세로 여백 8~12rem, 대표 글 행간 1.4.
 * 레이어 밖에 둔다 — 탭·목록의 색과 간격을 이 면 안에서 조정한다.
 */
.news-deck {
  --surface: var(--color-primary-90);
  --color-primary: var(--color-gray-0);
  --color-text-subtle: color-mix(in srgb, var(--color-primary-10) 75%, var(--color-primary-90));
  --color-border: color-mix(in srgb, var(--color-gray-0) 20%, transparent);
  --color-border-light: color-mix(in srgb, var(--color-gray-0) 12%, transparent);

  @apply pt-[8rem] pb-[4.8rem] laptop:pt-[12rem] laptop:pb-[6.4rem];
}

.news-deck__grid {
  @apply grid gap-[4.8rem] laptop:gap-[6.4rem] laptop:[grid-template-columns:minmax(0,1fr)_44rem];
}

/* 격자 칸이 내용 폭 때문에 넘치지 않게 */
.news-deck__board {
  @apply min-w-0;
}

/* 탭 — 선택 탭은 흰 글자 + 강조색 밑줄 */
.news-deck .tab__list {
  @apply gap-[0.4rem] shadow-[inset_0_-0.1rem_0_var(--color-border)];
}

.news-deck .tab__item {
  @apply px-[1.8rem];
}

.news-deck .tab__item::after {
  @apply left-[1.2rem] right-[1.2rem] h-[0.3rem];
}

.news-deck .tab__item[aria-selected="true"]::after {
  @apply bg-[var(--color-point-30)];
}

.news-deck .tab__panel {
  @apply pt-0 pb-0;
}

.news-deck .post-list {
  @apply border-t-0;
}

.news-deck .post-list__item {
  @apply py-[1.6rem];
}

.news-deck .post-list__link,
.news-deck .post-list__link:visited {
  @apply font-normal text-[var(--color-primary-10)];
}

.news-deck .post-list__link:hover {
  @apply text-[var(--color-gray-0)];
}

/* 첫 글 — 대표 글. KRDS 기준 밖(운영자 승인 대기): 행간 1.4(150% 기준) */
.news-deck .post-list__item:first-child {
  @apply py-[2.4rem] tablet:py-[3.2rem];
}

.news-deck .post-list__item:first-child .post-list__link {
  @apply [font-family:var(--font-heading)] text-[2.2rem] font-semibold leading-[1.4] text-[var(--color-gray-0)] [word-break:keep-all] tablet:text-[2.8rem] tablet:[-webkit-line-clamp:3];
}

.news-deck .more-link {
  @apply mt-[2rem] text-[var(--color-primary-20)] underline [text-underline-offset:0.35em];
}

.news-deck .more-link:visited {
  @apply text-[var(--color-primary-20)];
}

/* src/styles/6-components/due-track.css */
/**
 * Due Track — 마감 칸 (블록 카탈로그 news-deck의 부품 · design-intelligence §5-6·§6-3 N2)
 *   짙은 면 위의 한 칸. 남은 날수를 큰 숫자로 세우고, 그 옆에 제목·마감일, 아래에 남은 기간 막대를 둔다.
 *   막대는 그림이다(aria-hidden). 같은 내용이 항목마다 글자로 있다.
 *   --left: 막대 길이(마감까지 날수 ÷ 가장 먼 마감까지 날수, 최소 4%).
 *   오늘부터 마지막 마감까지의 시간축은 뺐다 — 막대와 같은 정보를 한 번 더 그렸다.
 *   <aside class="due-track" aria-labelledby="due-track-title" data-reveal>
 *     <h3 class="due-track__title" id="due-track-title">접수 중인 공모·모집</h3>
 *     <p class="due-track__asof">오늘 <time datetime="2026-11-13">11월 13일</time> 기준</p>
 *     <ol class="due-track__list" role="list">
 *       <li class="due-track__item"><a class="due-track__link" href="…">
 *         <span class="due-track__days"><strong class="due-track__count">8</strong>일 남음</span>
 *         <span class="due-track__body">
 *           <span class="due-track__name">제목</span>
 *           <span class="due-track__meta"><time datetime="…">11월 21일</time> 마감</span>
 *         </span>
 *         <span class="due-track__bar" style="--left: 47%" aria-hidden="true"><span class="due-track__fill"></span></span>
 *       </a></li>
 *     </ol>
 *   </aside>
 *   due-track__bar--warning: 마감이 7일 이내인 항목(강조색 막대). 남은 날수 글자로도 알 수 있다.
 *   막대는 화면에 들어올 때 한 번 차오른다 — src/js/reveal.js(data-reveal). 스크립트가 없거나 움직임 줄이기면 처음부터 차 있다.
 *   막대 채움은 단색 토큰이다(견본의 그라데이션 채움을 단색으로 바꿔 R-34 예외를 없앴다).
 *   블록 예외(contracts/block-exceptions.json): 1.2초 채움 움직임, 숫자 행간 1.1.
 * 레이어 밖에 둔다 — news-deck과 같은 층.
 */
.due-track {
  @apply flex flex-col p-[2.4rem] rounded-[1.2rem] bg-[var(--color-primary-80)] tablet:p-[3.2rem];
}

.due-track__title {
  @apply m-0 mb-[0.4rem] text-[2rem] font-bold leading-[1.5] [word-break:keep-all];
}

.due-track__asof {
  @apply m-0 text-[1.5rem] leading-[1.7] text-[var(--color-text-subtle)];
}

/* 칸이 목록 높이만큼 늘어나면 항목이 남는 높이를 나눠 갖는다 */
.due-track__list {
  @apply flex flex-1 flex-col justify-center list-none m-0 mt-[1.6rem] p-0;
}

.due-track__item {
  @apply border-t border-[var(--color-border-light)];
}

.due-track__link {
  @apply grid items-center gap-x-[2rem] py-[2.4rem] text-[var(--color-text)] no-underline [grid-template-columns:auto_minmax(0,1fr)] tablet:gap-x-[2.4rem] laptop:py-[3.2rem];
}

.due-track__link:visited {
  @apply text-[var(--color-text)];
}

.due-track__days {
  @apply text-[1.5rem] leading-[1.7] text-[var(--color-primary-10)] whitespace-nowrap;
}

/* 남은 날수 — 이 칸에서 가장 먼저 읽히는 글자. 한 줄 고정이라 행간을 좁힌다 */
.due-track__count {
  @apply block [font-family:var(--font-heading)] text-[5.6rem] font-semibold leading-[1.1] text-[var(--color-point-30)] whitespace-nowrap [font-variant-numeric:tabular-nums] tablet:text-[7.2rem];
}

.due-track__body {
  @apply flex flex-col gap-[0.4rem];
}

.due-track__name {
  @apply text-[1.9rem] font-bold leading-[1.5] [word-break:keep-all];
}

.due-track__link:hover .due-track__name {
  @apply underline;
}

.due-track__meta {
  @apply text-[1.5rem] leading-[1.7] text-[var(--color-text-subtle)] [font-variant-numeric:tabular-nums];
}

.due-track__bar {
  @apply relative block col-span-2 h-[0.8rem] mt-[1.6rem] rounded-[0.4rem] overflow-hidden;

  background-color: color-mix(in srgb, var(--color-gray-0) 8%, transparent);
}

.due-track__fill {
  @apply absolute inset-y-0 start-0 w-[var(--left)] rounded-[0.4rem] origin-left bg-[var(--color-primary-30)] [transition:transform_1.2s_cubic-bezier(0.2,0.8,0.2,1)];
}

.due-track__bar--warning .due-track__fill {
  @apply bg-[var(--color-point-30)];
}

[data-motion="on"] .due-track[data-reveal]:not([data-revealed]) .due-track__fill {
  transform: scaleX(0);
}

@media (prefers-reduced-motion: reduce) {
  .due-track__fill {
    @apply [transition:none];
  }
}

/* src/styles/6-components/post-list.css */
/**
 * Post List — 게시판 최신 글 목록: 제목 + 날짜 (블록 카탈로그 bulletin의 부품 · KS-04 목록 자리)
 *   제목은 768px 이상에서 두 줄까지 보이고(좁은 화면은 전부 보인다) 날짜는 오른쪽 열에 자릿수를 맞춘다.
 *   <ul class="post-list" role="list">
 *     <li class="post-list__item">
 *       <a class="post-list__link" href="…">제목</a>
 *       <time class="post-list__date" datetime="2026-10-15">2026.10.15</time>
 *     </li>
 *   </ul>
 * 레이어 밖에 둔다 — bulletin이 첫 글의 크기를 바꾼다.
 */
.post-list {
  @apply list-none m-0 p-0 border-t border-[var(--color-border)];
}

.post-list__item {
  @apply flex flex-col gap-[0.2rem] py-[0.4rem] border-b border-[var(--color-border-light)] tablet:flex-row tablet:items-baseline tablet:gap-[2.4rem] tablet:py-[1.2rem];
}

.post-list__link {
  @apply flex flex-1 items-center min-w-0 min-h-[4.4rem] tablet:min-h-0 text-[1.7rem] leading-[1.5] text-[var(--color-text)] no-underline [word-break:keep-all] tablet:overflow-hidden tablet:[display:-webkit-box] tablet:[-webkit-box-orient:vertical] tablet:[-webkit-line-clamp:2] [transition:color_0.15s_ease-in-out];
}

.post-list__link:visited {
  @apply text-[var(--color-text)];
}

.post-list__link:hover {
  @apply text-[var(--color-link-hover)] underline;
}

.post-list__date {
  @apply shrink-0 text-[1.5rem] leading-[1.5] text-[var(--color-text-subtle)] [font-variant-numeric:tabular-nums];
}

/* src/styles/6-components/more-link.css */
/**
 * More Link — 「<게시판명> 전체 보기」 링크 (블록 카탈로그 bulletin의 부품)
 *   이름에 목적지를 적는다 — 「더보기」만 쓰지 않는다(R-30).
 *   <a class="more-link" href="…">공지사항 전체 보기
 *     <svg class="icon icon--xsmall" aria-hidden="true"><use href="/assets/icons/sprite.svg#chevron-right"></use></svg>
 *   </a>
 * 레이어 밖에 둔다 — bulletin과 같은 층.
 */
.more-link {
  @apply inline-flex items-center gap-[0.4rem] min-h-[4.4rem] mt-[0.8rem] text-[1.7rem] font-bold leading-[1.5] text-[var(--color-text)] no-underline [transition:color_0.15s_ease-in-out];
}

.more-link:visited {
  @apply text-[var(--color-text)];
}

.more-link:hover {
  @apply text-[var(--color-link-hover)] underline;
}
